578	func (d *Downloader) notifyRunning() {
579		go func() {
580			d.lock.Lock()
581			defer d.lock.Unlock()
582	
583			remainRunningCount := d.remainRunningCount()
584			if remainRunningCount == 0 {
585				return
586			}
587			if len(d.waitTasks) > 0 {
588				wt := d.waitTasks[0]
589				d.waitTasks = d.waitTasks[1:]
590				d.doStart(wt)
591			}
592		}()
593	}
594	
595	func (d *Downloader) remainRunningCount() int {
596		runningCount := 0
597		for _, t := range d.tasks {
598			if d.taskStatus(t) == base.DownloadStatusRunning {
599				runningCount++
600			}
601		}
602		return d.cfg.MaxRunning - runningCount
603	}
