605	func (d *Downloader) CreateDirect(req *base.Request, opts *base.Options) (taskId string, err error) {
606		defaultPath, err := d.prepareDefaultPath(opts)
607		if err != nil {
608			return "", err
609		}
610		taskId, err = d.createDirect(req, opts)
611		if err == nil {
612			d.persistDefaultPathBestEffort(defaultPath)
613		}
614		return
615	}
