617	func (d *Downloader) createDirect(req *base.Request, opts *base.Options) (taskId string, err error) {
618		ensureRequestRawURL(req)
619		var fetcher fetcher.Fetcher
620		fetcher, err = d.buildFetcher(req.URL)
621		if err != nil {
622			return
623		}
624		fetcher.Meta().Req = req
625		initOpt, err := d.initOptions(opts, req.URL)
626		if err != nil {
627			return
628		}
629		return d.doCreate(fetcher, initOpt)
630	}
631	
632	func (d *Downloader) CreateDirectBatch(req *base.CreateTaskBatch) (taskId []string, err error) {
633		defaultPath, err := d.prepareDefaultPath(req.Opts)
634		if err != nil {
635			return nil, err
636		}
637		taskIds := make([]string, 0)
638		for _, ir := range req.Reqs {
639			opts := ir.Opts
640			if opts == nil {
641				opts = req.Opts
642			}
643			if opts != nil {
644				opts = opts.Clone()
645			}
646			taskId, err := d.createDirect(ir.Req, opts)
647			if err != nil {
648				return nil, err
649			}
650			taskIds = append(taskIds, taskId)
651		}
652		d.persistDefaultPathBestEffort(defaultPath)
653		return taskIds, nil
654	}
