	for manager.starts.Load() != 2 && time.Now().Before(deadline) {
		time.Sleep(5 * time.Millisecond)
	}
	if got := manager.starts.Load(); got != 2 {
		t.Fatalf("replacement task did not start: %d starts", got)
	}
